osures\":[],\"version\":21,\"id_type\":\"userID\",\"value\":{\"model_slugs\":[]},\"is_device_based\":false,\"passed\":false},\"1504865540\":{\"name\":\"1504865540\",\"rule_id\":\"default\",\"secondary_exposures\":[],\"version\":9,\"id_type\":\"userID\",\"value\":{\"max_file_size_mb\":25},\"is_device_based\":false,\"passed\":false},\"2347841422\":{\"name\":\"2347841422\",\"rule_id\":\"default\",\"secondary_exposures\":[{\"gate\":\"3191411446\",\"gateValue\":\"false\",\"ruleID\":\"default\"}],\"version\":34,\"id_type\":\"userID\",\"value\":{\"enabled_entity_categories\":[\"local_business\",\"restaurant\",\"product_rationale_and_reviews\"]},\"is_device_based\":false,\"passed\":false},\"3586803603\":{\"name\":\"3586803603\",\"rule_id\":\"default\",\"secondary_exposures\":[],\"version\":12,\"id_type\":\"userID\",\"value\":{\"default\":\"legacy\",\"app_modes\":{\"connector_openai_deep_research\":\"dns_safe_v1\",\"asdk_app_6a59aa7c1f50819184bcdac496bd4cb5\":\"dns_safe_v1\",\"asdk_app_6a17572299b48191b3edd38612c53f5b\":\"dns_safe_v1\"}},\"is_device_based\":false,\"passed\":false},\"2513446768\":{\"name\":\"2513446768\",\"rule_id\":\"default\",\"secondary_exposures\":[],\"version\":14,\"id_type\":\"userID\",\"value\":{\"retirement_date\":\"2026-12-11\",\"disable_gpt_creation_and_updates\":false,\"disable_gpt_creation\":false,\"learn_more_url\":\"https://help.openai.com/{lang}/collections/8475420-gpts\",\"disable_gpt_updates\":false},\"is_device_based\":false,\"passed\":false},\"3421588596\":{\"name\":\"3421588596\",\"rule_id\":\"default\",\"secondary_exposures\":[],\"version\":7,\"id_type\":\"userID\",\"value\":{\"default_average_monthly_credits_per_member\":400},\"is_device_based\":false,\"passed\":false},\"3939855767\":{\"name\":\"3939855767\",\"rule_id\":\"default\",\"secondary_exposures\":[],\"version\":5,\"id_type\":\"userID\",\"value\":{\"section_order\":[]},\"is_device_based\":false,\"passed\":false},\"216490582\":{\"name\":\"216490582\",\"rule_id\":\"default\",\"secondary_exposures\":[],\"version\":4,\"id_type\":\"userID\",\"value\":{\"url\":\"https://help.openai.com/articles/20001509\"},\"is_device_based\":false,\"passed\":false},\"2850107578\":{\"name\":\"2850107578\",\"rule_id\":\"7nxmtzMrThjQ6ucoe2XHVB:100.00:21-7nxmty7pqZalN4EsCV24Cz\",\"secondary_exposures\":[{\"gate\":\"3796009202\",\"gateValue\":\"true\",\"ruleID\":\"70knO3S2IIQ3C4K3vmxsog:100.00:1\"}],\"version\":55,\"id_type\":\"userID\",\"value\":{\"android_large_font_scale_threshold\":1.5,\"ask_chatgpt_system_message\":\"The user is referring to an ad shown to them about: {LABEL}. Your response MUST BE ABOUT THE ADS shown, since the user explicitly asked about them. They are using the 'Ask ChatGPT' feature and you must reply to the user query using the information about the ads, which is:\\n{DATA}\\n\\nFor example: if the user asks 'Tell me more about these' (or other wordings), then your answer should be about details or further information on products, services, locations etc described in the ad and the links in the ad.\",\"onboarding\":{\"impression_count\":5,\"card_image_url\":\"https://cdn.openai.com/chatgpt/clients/onboarding/onboarding-example-1.png\",\"screen_trust_image_url_when_personalization_unavailable\":\"https://cdn.openai.com/chatgpt/clients/bazaar/onboarding/personalization_unavailable_trust_v1.jpg\",\"screen_privacy_image_url\":\"https://cdn.openai.com/chatgpt/clients/bazaar/onboarding/secure.png\",\"screen_transparency_image_url\":\"https://cdn.openai.com/chatgpt/clients/bazaar/onboarding/controls_en.png\",\"screen_transparency_image_url_when_personalization_unavailable\":\"https://cdn.openai.com/chatgpt/clients/bazaar/onboarding/personalization_unavailable_transparency_v1.jpg\",\"screen_trust_image_url\":\"https://cdn.openai.com/chatgpt/clients/bazaar/onboarding/trusted_en.png\",\"screen_personalization_image_url\":\"https://cdn.openai.com/chatgpt/clients/bazaar/onboarding/personalization_en.png\"},\"android_display_zoom_scale_threshold\":1,\"lat